const assert = require('node:assert');
const { parseAll } = require('./parse.js');

assert.deepStrictEqual(parseAll(['1', '2', '3', '10']), [1, 2, 3, 10]);
assert.deepStrictEqual(parseAll(['42']), [42]);
assert.deepStrictEqual(parseAll([]), []);
assert.deepStrictEqual(parseAll(['100', '200', '300']), [100, 200, 300]);

console.log('ok');

